var a=`1380-guyanese-pepperpot`;var i=`world-1380`;var n=`GY`;var s=`south-america`;var o=4;var r=174;var l={en:`Guyanese Pepperpot`,ua:`Гаянський пеперпот`};var p={en:`Guyanese Pepperpot is a dish from Guyana featuring beef chuck, yellow onion, garlic, thyme. This home-sized recipe records each ingredient at the step where it is used. Cassareep, the defining bitter-cassava reduction, is absent. Tamarind and molasses are NOT equivalent; this is pepperpot-inspired beef stew only.`,ua:`Гаянський пеперпот, страва кухні країни Гаяна з такими основними складниками: яловича лопатка, жовта цибуля, часник, чебрець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Касаріп, визначальний редукований сік гіркого маніоку, відсутній. Тамаринд із мелясою НЕ є рівноцінною заміною; це лише тушкована яловичина за мотивами пеперпоту.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,850,`g`],[`canola-oil`,40,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,175,`g`],[`garlic`,5,`clove`],[`thyme`,4,`sprig`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 150 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 150 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:150,i:[[`beef-stock`,1e3,`ml`],[`tamarind-concentrate`,40,`g`],[`blackstrap-molasses`,80,`g`],[`cassia-cinnamon`,6,`g`],[`allspice-berries`,7,`pcs`]]},{en:`Season the tender beef stew to taste and serve hot. Without cassareep its flavor is only pepperpot-inspired.`,ua:`Приправте м’яку тушковану яловичину до смаку й подавайте гарячою. Без касаріпу це лише адаптація за мотивами пеперпоту.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]}];var d={slug:a,id:i,country:`GY`,region:s,servings:4,minutes:174,title:l,text:p,steps:u};export{n as country,d as default,i as id,r as minutes,s as region,o as servings,a as slug,u as steps,p as text,l as title};